    marks=''.join(f'<path d="M360 146v{12 if i%5==0 else 5}" transform="rotate({i*6} 360 240)" stroke="#c7b484" stroke-width="{2 if i%5==0 else 1}"/>' for i in range(60))
    return '''<path d="M320 33h80l13 126H307ZM309 326h103l-13 126h-79Z" fill="#474a43"/><path d="M329 37h62m-73 47h84m-90 32h96m-96 250h96m-92 29h86m-81 30h78" stroke="#717367" stroke-width="1"/><circle cx="360" cy="242" r="110" fill="#101713" stroke="url(#gold)" stroke-width="7"/><circle cx="360" cy="240" r="95" fill="#252f29" stroke="#aaa078"/>'''+marks+'''<circle cx="360" cy="240" r="62" fill="none" stroke="#70776a" stroke-width=".5"/><path d="M360 240 320 203M360 240l47-55" stroke="#dfd5b6" stroke-width="4"/><path d="m360 240 26 38" stroke="#b08c50" stroke-width="1.5"/><circle cx="360" cy="240" r="5" fill="url(#gold)"/><rect x="469" y="228" width="13" height="24" rx="3" fill="url(#gold)"/><text x="360" y="199" fill="#e5dbbd" text-anchor="middle" font-family="Georgia" font-size="9" letter-spacing="2">TIME, SLOWLY</text>'''

